            logical.append(buf)
        buf = line
    else:
        buf = (buf + ' ' + line) if buf is not None else line"""
new = """    # a real subject line ends with '.' (possibly after a trailing object);
    # continuation lines like 'uni:hasName "ETH Zurich" ;' do not
    if re.match(r'^uni:[A-Za-z0-9_]+\\s', line) and line.rstrip().endswith('.'):
        if buf is not None:
            logical.append(buf)
        buf = line
    else:
        buf = (buf + ' ' + line) if buf is not None else line"""
assert old in s
open(p,'w',encoding='utf-8').write(s.replace(old,new))
